NEW_FILES = {'migrations/migrate_bank_dress.py': '#!/usr/bin/env python3\n"""\nmigrate_bank_dress.py  --  a bank\'s cameras, plants and clock (0.282.0)\n========================================================================\nOne-shot, idempotent migration over specs/*.json. Furnish hangs Zoo\'s `security_camera` in a bank\'s lobby and in each\nof its vaults (two a room, four in a room of 300 m2 or more), stands its lobby\'s potted plants (Zoo\'s `planter`, up to\nthree) and hangs its wall clock (Zoo\'s `wall_clock`) -- the `bank_lobby` and `bank_vault` recipes. The\nlibrary is a fixed point of its furnishing pass, so every spec with a room of either kind is refurnished\n(`migrate_furnish_recipes.migrate`); no other spec is touched.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_bank_dress.py            # write specs/\n    python migrations/migrate_bank_dress.py --check    # report only; exit 1 if any would change\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\n\nKINDS = ("bank_lobby", "bank_vault")\n\n\ndef _touched(d):\n    b = level_design.club_building_id(d)\n    return any(level_design._room_kind(r, b) in KINDS for r in d.get("rooms") or [])\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    changed = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not _touched(d):\n            continue\n        before = json.dumps(d, indent=1) + "\\n"\n        migrate_furnish_recipes.migrate(d)\n        after = json.dumps(d, indent=1) + "\\n"\n        if after == before:\n            continue\n        changed += 1\n        names = [str(v.get("name", "")) for v in d["volumes"]]\n        print(f"[bank_dress] {os.path.basename(p)}: {sum(n.startswith(\'security_camera\') for n in names)} camera(s), "\n              f"{sum(n.startswith(\'potted_plant\') for n in names)} plant(s), "\n              f"{sum(n.startswith(\'wall_clock\') for n in names)} clock(s)")\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(after)\n    verb = "would change" if check else "refurnished"\n    print(f"[bank_dress] {changed} spec(s) {verb}")\n    return 1 if check and changed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_bank_walls_cameras.py': '"""A bank\'s walls are finished inside, and it hangs CCTV cameras, keeps potted plants and a wall clock (0.282.0, the\nfactory\'s roadmap 321).\n\nThe walker\'s bank comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md) paint every public room\'s walls; a bank\nbuilt of concrete showed raw concrete in its lobby and offices (docs/findings/bank_interior/, frames 01-06). And the\nwalker asked "were there cctv cameras in the 90s?": yes, since the Bank Protection Act of 1968 -- Zoo\'s\n`security_camera`, which no building placed.\n\nThe comps keep plants in planters by the windows and counters and a clock over the line (Zoo 1.136.0\'s `planter` and\n`wall_clock`); a `potted_plant`, because `planter` is the library\'s long planter boxes, which stay boxes.\n\nFAILS ON 0.281.0: a bank\'s concrete walls carry no `material_in`, and no bank hangs a camera, a plant or a clock.\n"""\nimport json\nimport math\nimport os\n\nimport pytest\n\nimport level_design\nimport prop_species\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBUILD = os.path.join(HERE, "build")\nBANKS = ("bank_branch_a02", "bank_branch_a03", "bank_branch_a04", "bank_job", "bank_tower_a01", "bank_tower_a02",\n         "bank_tower_a03")\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _in(v, room):\n    x0, y0, x1, y1 = room["bounds"]\n    return x0 <= v.get("x", 1e9) <= x1 and y0 <= v.get("y", 1e9) <= y1\n\n\ndef _story(d, v):\n    """The storey a hung piece is in, by its CENTRE: `level_design._volume_story` guesses from a volume\'s base and\n    rounds, so a camera under a basement\'s ceiling (base -0.8 m at a 3.6 m storey) reads as the ground floor -- the\n    first reading of this test\'s counts was that misreading, not the placement."""\n    return int(math.floor(float(v["z"]) / float(d.get("story_height") or 3.6)))\n\n\ndef test_the_camera_routes_to_zoos_species_long_in_depth():\n    assert prop_species.species_for_name("security_camera_rcce455f7_7") == "security_camera"\n    assert "security_camera" in prop_species.DEPTH_LONG\n    p = level_design._PIECES["security_camera"]\n    assert p["where"] == "wall" and p["collision"] == "none" and p["under"]\n    assert "security_camera" in level_design._RECIPES["bank_lobby"]["fixtures"]\n    assert "security_camera" in level_design._RECIPES["bank_vault"]["fixtures"]\n    assert "security_camera" not in (level_design._RECIPES["lobby"].get("fixtures") or ())\n\n\ndef test_every_bank_hangs_cameras_in_its_lobby_and_vaults():\n    for name in BANKS:\n        d = _spec(name)\n        b = level_design.club_building_id(d)\n        cams = [v for v in d["volumes"] if v["name"].startswith("security_camera")]\n        lobbies = [r for r in d["rooms"] if level_design._room_kind(r, b) == "bank_lobby"]\n        assert lobbies, name\n        for r in lobbies:\n            story = int(r.get("story", 0) or 0)\n            here = [v for v in cams if _in(v, r) and _story(d, v) == story]\n            assert len(here) >= 2, (name, r["id"], len(here))\n        vaults = [r for r in d["rooms"] if level_design._room_kind(r, b) == "bank_vault"]\n        assert vaults, name\n        for r in vaults:\n            story = int(r.get("story", 0) or 0)\n            assert [v for v in cams if _in(v, r) and _story(d, v) == story], (name, r["id"])\n        # every camera hangs above a head and below its own storey\'s ceiling\n        sh = float(d.get("story_height") or 3.6)\n        for v in cams:\n            s = _story(d, v)\n            top = float(v["z"]) + float(v["size_z"]) / 2.0 - s * sh\n            assert 2.0 < top <= sh, (name, v["name"], top)\n\n\ndef test_no_other_building_hangs_one():\n    import glob\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        n = os.path.basename(p)[:-5]\n        if n.startswith("lf_") or n in BANKS:\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        assert not any(str(v.get("name", "")).startswith("security_camera") for v in d.get("volumes") or []), n\n\n\n@pytest.mark.parametrize("name", BANKS)\ndef test_a_banks_concrete_walls_are_plaster_inside_above_grade_and_concrete_below(name):\n    path = os.path.join(BUILD, name + ".slots.json")\n    if not os.path.exists(path):\n        pytest.skip("%s is not built" % name)\n    slots = json.load(open(path, encoding="utf-8"))["slots"]\n    above = below = 0\n    for s in slots:\n        parts = str(s.get("wall") or "").split("_")\n        if not (len(parts) >= 3 and parts[0] == "ext" and s.get("material") == "concrete"\n                and s.get("role") in ("wall", "window", "doorway", "breach") and not s.get("glazing")):\n            continue\n        if int(parts[1]) >= 0:\n            above += 1\n            assert s.get("material_in") == "plaster", (name, s["slot_id"])\n        else:\n            below += 1\n            assert "material_in" not in s, (name, s["slot_id"])\n    assert above, name\n\n\ndef test_the_plant_and_the_clock_route_to_zoos_species_and_the_planter_boxes_stay_boxes():\n    assert prop_species.species_for_name("potted_plant_rcce455f7_8") == "planter"\n    assert prop_species.species_for_name("wall_clock_rcce455f7_9") == "wall_clock"\n    assert prop_species.species_for_name("planter_r1234abcd_2") is None\n    r = level_design._RECIPES["bank_lobby"]\n    assert "potted_plant" in r["wall"] and "wall_clock" in r["fixtures"]\n\n\ndef test_every_banks_lobby_keeps_plants_and_a_clock():\n    for name in BANKS:\n        d = _spec(name)\n        b = level_design.club_building_id(d)\n        for r in [r for r in d["rooms"] if level_design._room_kind(r, b) == "bank_lobby"]:\n            story = int(r.get("story", 0) or 0)\n            mine = [v["name"] for v in d["volumes"] if _in(v, r) and _story(d, v) == story]\n            assert sum(n.startswith("potted_plant") for n in mine) >= 1, (name, r["id"])\n            assert sum(n.startswith("wall_clock") for n in mine) == 1, (name, r["id"])\n'}
CHANGELOG = '## [0.282.0] - a bank\'s walls are plastered inside, and it hangs CCTV cameras, keeps plants and a clock\n\nThe walker, shown the furnished bank (0.281.0): "fix it before we rush to the release". Then "were there cctv cameras in\nthe 90s?" and "cameras first". Against the comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md), every frame of\nthe bank showed raw concrete walls in its lobby and offices, and it had no camera (docs/findings/bank_interior/).\n\n### Added\n- **A bank\'s walls are finished inside** (`DeliCounter.BANK_INTERIOR`, `_is_bank`, `_material_in`).\n  - A bank\'s concrete exterior walls above grade carry `material_in` plaster, the comps\' painted walls.\n    - Concrete reads "the same both sides" and took no room face, so a concrete bank showed concrete in its lobby.\n    - bank_branch_a02: 108 wall slots plastered inside.\n  - Below grade the money rooms stay concrete: 56 of bank_branch_a02\'s slots, the comps\' "hard rooms".\n  - Every other building\'s walls are what they were.\n- **`security_camera`**, a piece: Zoo\'s species, a CCTV camera on its wall bracket, which no building placed.\n  - Its basis: the Bank Protection Act of 1968 asks for devices that identify a robber, and banks met it with\n    interior cameras recorded on time-lapse VCRs (the reference\'s "researched" section).\n  - Hung on a wall facing the room, its top `_CAMERA_AIR` (0.25 m) under the ceiling, out of reach, so no collision.\n  - Two a room, four in a room of 300 m2 or more.\n  - A fixture of `bank_lobby` and `bank_vault`. bank_branch_a02 hangs 14: four in its lobby, and four, four and two\n    in its vaults.\n- `prop_species` routes it, and `DEPTH_LONG` lists it: its genome is longer in depth than in width, which\n  `test_depth_long` holds.\n- **`potted_plant`** and **`wall_clock`**, pieces: Zoo 1.136.0\'s `planter` and `wall_clock`, the comps\' plants by the\n  windows and counters and the clock over the line.\n  - The plant stands against a wall, its variant the plant, two in the lobby\'s wall pool. The clock hangs at 2.3 m, one\n    a lobby.\n  - A `potted_plant`, not a `planter`: that word is the library\'s long planter BOXES (1.4 x 0.7 m and 2.4 x 1.4 m,\n    fifteen in seven specs), outside the species\' range, and they stay boxes.\n- **The ATM is a bank lobby\'s anchor** (`all_anchors`), placed before any wall piece. With three plants in the wall\n  pool, bank_branch_a03\'s took the wall its ATM and chairs had stood on. `test_ticket_queue`, which holds that a queued\n  lobby keeps its ATM, failed on the clone\'s full suite.\n- **`migrations/migrate_bank_dress.py`** refurnishes the seven banks and nothing else: 6-14 cameras, 2-4 plants and one\n  clock a bank.\n\n### Tests\n- `tests/test_bank_walls_cameras.py` (fails on 0.281.0):\n  - the camera routes to Zoo\'s species, long in depth, and only the bank recipes hang it;\n  - every bank hangs cameras in its lobby and in each vault, above a head and below its own storey\'s ceiling;\n  - the plant and the clock route to Zoo\'s species, and the planter boxes stay boxes;\n  - every bank\'s lobby keeps a plant and one clock;\n  - no other building hangs one;\n  - a bank\'s concrete walls are plaster inside above grade and concrete below.\n  - The test reads a hung piece\'s storey by its CENTRE. `level_design._volume_story` rounds from the base, so a camera\n    under a basement\'s ceiling read as the ground floor. The first count of the placement was that misreading.\n- `test_inner_face` allows a bank\'s plastered concrete beside the outside-only finishes it held.\n- `test_furnish`:\n  - mirrors the camera\'s, the planter\'s and the clock\'s sizes;\n  - reads a species long in DEPTH short side first, as `prop_species.long_axis_first` records it. It compared the\n    camera\'s 0.38 m depth against Zoo\'s 0.24 m maximum width. Found by the full suite on the clone, which also had no\n    range for the camera.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.281.0', 'Deli Counter 0.282.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
